This PR implements AutoCloseable in SerializableTableWithSize to make sure resources used by copies of the table on executors are released correctly.
See freeMemoryEntry in MemoryStore.
def freeMemoryEntry[T <: MemoryEntry[_]](entry: T): Unit = {
  entry match {
    case SerializedMemoryEntry(buffer, _, _) => buffer.dispose()
    case e: DeserializedMemoryEntry[_] => e.value.foreach {
      case o: AutoCloseable =>
        try {
          o.close()
        } catch {
          case NonFatal(e) =>
            logWarning("Fail to close a memory entry", e)
        }
      case _ =>
    }
  }
}
